		sb.Append('$');
		segments.Pop();  // first is always null - the root
		while (segments.Count != 0)
		{
			var segment = segments.Pop();
			var index = segment?.GetNumber();
			sb.Append(index != null ? $"[{index}]" : GetNamedSegmentForPath(segment!, useShorthand));
		}

