		new ArrayExpressionParser(),
		new UnaryExpressionParser(),
		new ContextAccessorExpressionParser(),
		new PrimitiveExpressionParser(),
	};

	public static ExpressionNode Parse(ReadOnlySpan<char> source)
	{
