			name = null;
			return false;
		}

		name = source[index..i].ToString();
		index = i;
		return true;
	}

	private static bool IsValidForPropertyName(this char ch)
	{
		return ch.In('a'..('z' + 1)) ||
		       ch.In('A'..('Z' + 1)) ||
		       ch.In('0'..('9' + 1)) ||
		       ch.In('_') ||
		       ch.In(0x80..0x10FFFF);
	}

