	public void NonEmptyArrayIsFalse()
	{
		var rule = new NotRule(JsonNode.Parse("[1]"));

		JsonAssert.IsFalse(rule.Apply());
	}

	[Test]
	public void EmptyStringIsTrue()
	{
		var rule = new NotRule("");

		JsonAssert.IsTrue(rule.Apply());
	}

