	{
		var buildOptions = new BuildOptions { SchemaRegistry = new() };
		JsonSchema schema = new JsonSchemaBuilder(buildOptions)
			.Schema(MetaSchemas.ArrayExt_202012Id)
			.Type(SchemaValueType.Array)
