		new JsonSchemaBuilder()
			.Schema(MetaSchemas.Data_202012Id)
			.Type(SchemaValueType.Object)
			.Properties(
				("foo", new JsonSchemaBuilder()
					.Type(SchemaValueType.Integer)
					.OptionalData(("minimum", "/minValue"))
