			}
			catch
			{
				continue;
			}

			if (string.IsNullOrEmpty(candidate) || usedPropertyNames.Contains(candidate)) continue;

			usedPropertyNames.Add(candidate);
			generatedNames.Add(candidate);
		}

		return generatedNames.ToArray();
	}
