	/// <summary>
	/// Intersects two sets.
	/// </summary>
	public static NumberRangeSet operator *(NumberRangeSet left, NumberRangeSet right) => Intersect(left, right);

	/// <summary>
	/// Calculates the complement (inversion) of a set.
	/// </summary>
