			  "type": "object",
			  "properties": {
			    "Value": {
			      "type": "integer",
			      "minimum": {{minValue}},
			      "maximum": {{maxValue}},
			      "exclusiveMinimum": {{minValue}},
			      "exclusiveMaximum": {{maxValue}}
			    }
			  }
			}
			""").RootElement;

		Assert.That(expected.IsEquivalentTo(schema.Root.Source));
	}
