			);

		JsonSchema actual = new JsonSchemaBuilder(new BuildOptions{SchemaRegistry = new()}).FromType<ShouldRefToExternalSchemaUsingIdAttribute>();

		AssertionExtensions.AssertEqual(expected, actual);
	}
