		if (typeSymbol is IArrayTypeSymbol arrayType)
		{
			result = (
				GetSchemaPropertyName(arrayType),
				SchemaCodeEmitter.ToUrn(arrayType.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat)),
				arrayType.ContainingAssembly
			);
			return true;
		}

		result = default;
		return false;
	}

