			if (groupTypes.Count <= 1) continue;

			var canonical = groupTypes
				.FirstOrDefault(t => IsPreferredCollectionShape(t.TypeSymbol))
				?? groupTypes.OrderBy(t => t.FullyQualifiedName, StringComparer.Ordinal).First();

