			.Where(t => t.Kind == TypeKind.Dictionary)
			.Where(t => !string.IsNullOrEmpty(GetDictionaryShapeKey(t.TypeSymbol)))
			.GroupBy(t => GetDictionaryShapeKey(t.TypeSymbol));

		foreach (var group in dictionaryGroups)
