			{
				Type = ConditionalTriggerType.Equality,
				PropertyName = propertyName!,
				PropertySchemaName = schemaName,
				ExpectedValue = useNumbers ? enumValue.ToString() : $"\"{enumMember.Name}\""
			};

			conditionalInfo.Triggers.Add(trigger);
		}

