	[Test]
	public static async Task ConcurrentSchemaDeserialization()
	{
		var options = new JsonSerializerOptions
		{
			TypeInfoResolverChain = { TestSerializerContext.Default },
			WriteIndented = true,
			Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
			Converters = { new ValidatingJsonConverter {EvaluationOptions = { OutputFormat = OutputFormat.List } } }
		};

		// Build distinct schemas so each deserialization registers a different schema in the registry
		var serializedSchemas = Enumerable.Range(0, 1000).Select(i =>
		{
			var schema = new JsonSchemaBuilder()
				.Type(SchemaValueType.Object)
				.Properties(
					($"prop{i}", new JsonSchemaBuilder().Type(SchemaValueType.String)))
				.Build();

			return JsonSerializer.Serialize(schema, options);
		});

		// Deserialize all schemas concurrently to stress the SchemaRegistry
		var tasks = serializedSchemas.Select(json => Task.Run(() => JsonSerializer.Deserialize<JsonSchema>(json, options)));

		var results = await Task.WhenAll(tasks);

		foreach (var result in results)
		{
			Assert.That(result, Is.Not.Null, "Each concurrent deserialization should produce a non-null schema.");
		}
	}

	[Test]
	public void EnumKeyedDictionaryRoundTrip()
	{
		var dictionary = new Dictionary<ValidatedEnum, string>
		{
			[ValidatedEnum.One] = "1",
			[ValidatedEnum.Two] = "2",
			[ValidatedEnum.Three] = "3"
		};
		var options = new JsonSerializerOptions
		{
			TypeInfoResolverChain = { TestSerializerContext.Default },
			WriteIndented = true,
			Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
			Converters = { new ValidatingJsonConverter { EvaluationOptions = { OutputFormat = OutputFormat.List } } }
		};

		var serialized = JsonSerializer.Serialize(dictionary, options);
		var deserialized = JsonSerializer.Deserialize<Dictionary<ValidatedEnum, string>>(serialized, options);

		Assert.That(deserialized, Is.EquivalentTo(dictionary));
	}

	/// <summary>
	/// The validation result is passed in the <see cref="Exception.Data"/>
	/// property under the `"validation"` key.
	/// </summary>
	private static void HandleException(Exception e)
	{
		TestConsole.WriteLine(e);
		TestConsole.WriteLine();
		if (e.Data.Contains("validation"))
		{
			var validation = (EvaluationResults)e.Data["validation"]!;
			TestConsole.WriteLine(JsonSerializer.Serialize(validation, _options));
		}
	}
