			var schemeEnd = value.IndexOf("://");
			if (schemeEnd >= 0)
			{
				var userinfo = value.Substring(schemeEnd + 3, atIndex - schemeEnd - 3);
				if (userinfo.IndexOf('[') >= 0 || userinfo.IndexOf(']') >= 0)
