		if (!System.Uri.TryCreate(value, UriKind.Absolute, out var uri))
			return false;

		// Must have a proper scheme (reject UNC paths)
		return !string.IsNullOrEmpty(uri.Scheme) && value.IndexOf(':') > 0;
	}

