	// Reject invalid characters per RFC3987 (IRI)
	// Must not contain: backslash, space, <, >, {, }, |, ^, `, "
	private static bool IsValidForIri(char ch)
	{
		return ch is not ('\\' or ' ' or '<' or '>' or '{' or '}' or '|' or '^' or '`' or '"');
