				if (next == 'a' || // alert/bell
				    next == 'e' || // escape
				    next == 'A' || // start of string (use ^ in ECMA-262)
				    next == 'G' || // end of previous match
				    next == 'z' || // end of string before newline (use $ in ECMA-262)  
				    next == 'Z')   // end of string (use $ in ECMA-262)
